<script setup lang="ts">
import{onMounted,ref}from'vue';import{api}from'../api';import{ElMessage}from'element-plus';const rows=ref<any[]>([]),detail=ref<any>(null),dialog=ref(false),scores=ref<any[]>([]);
async function load(){rows.value=await api.pendingGrades()}async function open(id:number){detail.value=await api.gradingDetail(id);scores.value=detail.value.attempt.questions.filter((q:any)=>q.type==='SUBJECTIVE').map((q:any)=>({questionId:q.questionId,score:0,comment:''}));dialog.value=true}
async function submit(){await api.manualGrade(detail.value.attempt.attemptId,{scores:scores.value});ElMessage.success('阅卷完成');dialog.value=false;load()}onMounted(load);
</script>
<template><div class="page"><div class="page-header"><div><h2 class="page-title">人工阅卷</h2><p class="muted">客观题自动评分，主观题在此完成评分</p></div><el-button @click="load">刷新</el-button></div><div class="content-card"><el-table :data="rows"><el-table-column prop="attemptId" label="考试记录"/><el-table-column prop="examId" label="考试ID"/><el-table-column prop="objectiveScore" label="客观题得分"/><el-table-column prop="status" label="状态"><template #default><el-tag type="warning">待人工阅卷</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button type="primary" link @click="open(s.row.attemptId)">开始阅卷</el-button></template></el-table-column></el-table><el-empty v-if="!rows.length" description="暂无待阅卷试卷"/></div><el-dialog v-model="dialog" title="主观题阅卷" width="700px"><template v-if="detail"><p>考生：{{detail.studentName}}　考试：{{detail.attempt.examTitle}}　客观题得分：{{detail.objectiveScore}}</p><div v-for="s in scores" :key="s.questionId" class="content-card" style="margin:12px 0"><h4>{{detail.attempt.questions.find((q:any)=>q.questionId===s.questionId)?.content}}</h4><p>考生答案：{{detail.attempt.questions.find((q:any)=>q.questionId===s.questionId)?.answer||'未作答'}}</p><el-input-number v-model="s.score" :min="0" :max="Number(detail.attempt.questions.find((q:any)=>q.questionId===s.questionId)?.score||0)" :precision="1"/><span class="muted"> / {{detail.attempt.questions.find((q:any)=>q.questionId===s.questionId)?.score}} 分</span><el-input v-model="s.comment" placeholder="评语（可选）" style="margin-top:10px"/></div></template><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="submit">提交评分</el-button></template></el-dialog></div></template>
